components.css:
.ds-button-primary{display:inline-flex;align-items:center;justify-content:center;height:32px;padding:0 10px;border:1px solid transparent;border-radius:var(--radius);background:var(--primary);color:var(--primary-foreground);font:500 14px/1 var(--font-sans);white-space:nowrap;transition:all 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-button-primary:hover{background:color-mix(in oklch,var(--primary) 80%,transparent)}
.ds-button-primary:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.ds-button-primary:active{transform:translateY(1px)}
.ds-button-primary:disabled{opacity:.5;cursor:not-allowed}

.ds-button-outline{display:inline-flex;align-items:center;justify-content:center;height:32px;padding:0 10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--background);color:var(--foreground);font:500 14px/1 var(--font-sans);white-space:nowrap;transition:all 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-button-outline:hover{background:var(--muted);color:var(--foreground)}
.ds-button-outline:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.ds-button-outline:active{transform:translateY(1px)}
.ds-button-outline:disabled{opacity:.5;cursor:not-allowed}
:host-context(.dark) .ds-button-outline{border-color:var(--input);background:color-mix(in oklch,var(--input) 30%,transparent)}
:host-context(.dark) .ds-button-outline:hover{background:color-mix(in oklch,var(--input) 50%,transparent)}

.ds-button-ghost{display:inline-flex;align-items:center;justify-content:center;height:32px;padding:0 10px;border:1px solid transparent;border-radius:var(--radius);background:transparent;color:var(--foreground);font:500 14px/1 var(--font-sans);white-space:nowrap;transition:all 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-button-ghost:hover{background:var(--muted);color:var(--foreground)}
.ds-button-ghost:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.ds-button-ghost:active{transform:translateY(1px)}
.ds-button-ghost:disabled{opacity:.5;cursor:not-allowed}
:host-context(.dark) .ds-button-ghost:hover{background:color-mix(in oklch,var(--muted) 50%,transparent)}

.ds-search-field{display:block;width:100%;height:34px;padding:0 43px 0 32px;border:1px solid transparent;border-radius:7px;background:var(--muted);color:var(--foreground);font:400 12px var(--font-sans);transition:color 150ms cubic-bezier(0.4,0,0.2,1),background-color 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-search-field::placeholder{color:var(--muted-foreground)}
.ds-search-field:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
:host-context(.dark) .ds-search-field{background:color-mix(in oklch,var(--input) 30%,transparent)}
@media(max-width:767px){.ds-search-field{height:40px;font-size:14px}}

.ds-tag-chip{display:inline-flex;align-items:center;gap:5px;padding:3px 7px;border-radius:4px;background:color-mix(in srgb,var(--tag-color) 12%,var(--background));color:var(--foreground);font:400 10px var(--font-sans)}
.ds-tag-chip[data-color="gray"]{--tag-color:#737373}
.ds-tag-chip[data-color="red"]{--tag-color:#ef4444}
.ds-tag-chip[data-color="orange"]{--tag-color:#f97316}
.ds-tag-chip[data-color="yellow"]{--tag-color:#eab308}
.ds-tag-chip[data-color="green"]{--tag-color:#22c55e}
.ds-tag-chip[data-color="blue"]{--tag-color:#3b82f6}
.ds-tag-chip[data-color="purple"]{--tag-color:#a855f7}
.ds-tag-chip[data-color="pink"]{--tag-color:#ec4899}
.ds-tag-chip button{padding:1px;border:0;border-radius:2px;background:transparent;color:inherit}
.ds-tag-chip button:hover{background:color-mix(in oklch,var(--foreground) 8%,transparent)}
.ds-tag-chip button:focus-visible{outline:2px solid var(--foreground);outline-offset:3px}

.ds-writing-surface{width:100%;max-width:740px;margin:0 auto;padding:44px 44px 80px;color:var(--foreground);font-family:var(--font-sans)}
.ds-writing-surface[data-width="wide"]{max-width:none}
.ds-writing-surface time{display:block;margin-bottom:18px;color:var(--muted-foreground);font-size:11px}
.ds-note-title{display:block;width:100%;margin:0;padding:0;overflow:hidden;resize:none;border:0;border-radius:0;background:transparent;color:var(--foreground);font:550 26px/1.4 var(--font-sans);letter-spacing:-.035em}
.ds-note-title:focus-visible{outline:none;background:var(--muted);border-radius:4px}
.ds-note-body{font:400 14px/1.65 var(--font-sans)}
.ds-note-body > *{margin:0;padding:4px 0}
.ds-note-body h1,.ds-note-body h2,.ds-note-body h3,.ds-note-body h4,.ds-note-body h5,.ds-note-body h6{line-height:1.35;font-weight:600;padding:10px 0 4px}
.ds-note-body h1{font-size:24px}
.ds-note-body h2{font-size:20px}
.ds-note-body h3{font-size:18px}
.ds-note-body h4{font-size:16px}
.ds-note-body h5{font-size:15px}
.ds-note-body h6{font-size:14px}
.ds-note-body pre{overflow:auto;padding:20px 24px;border-radius:8px;background:#171717;color:#ededed;font:12px/1.7 var(--font-mono)}
@media(max-width:1100px){.ds-writing-surface{padding:42px 36px 80px}}
@media(max-width:1023px){.ds-writing-surface{max-width:760px}}
@media(max-width:767px){.ds-writing-surface{padding:32px 26px 80px}.ds-note-title{font-size:24px}.ds-note-body{font-size:16px}.ds-note-body h5,.ds-note-body h6{font-size:16px}}

.ds-settings-tabs{display:flex;gap:24px;padding:0 28px;border-bottom:1px solid var(--border);font-family:var(--font-sans)}
.ds-settings-tabs button{min-height:44px;padding:0;border:0;border-bottom:2px solid transparent;margin-bottom:-1px;background:transparent;color:var(--muted-foreground);font:400 13px var(--font-sans);white-space:nowrap;transition:color 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-settings-tabs button[aria-selected="true"]{color:var(--foreground);border-color:var(--foreground)}
.ds-settings-tabs button:hover{color:var(--foreground)}
.ds-settings-tabs button:focus-visible{outline:2px solid var(--foreground);outline-offset:3px}
@media(max-width:767px){.ds-settings-tabs{gap:20px;padding:0 22px}.ds-settings-tabs button{font-size:12px}}

.ds-artifact-shelf{color:var(--foreground);font-family:var(--font-sans)}
.ds-artifact-drop{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px;padding:16px;border:1px dashed var(--border);border-radius:var(--radius);color:var(--muted-foreground);font-size:13px}
.ds-artifact-drop p{margin:0}.ds-artifact-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.ds-artifact-actions button{display:inline-flex;align-items:center;justify-content:center;min-height:32px;padding:0 10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--background);color:var(--foreground);font:500 14px var(--font-sans);white-space:nowrap}
.ds-artifact-actions button:hover{background:var(--muted)}
.ds-artifact-actions button:focus-visible{border-color:var(--foreground);outline:none}
.ds-artifact-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px;margin:0;padding:0;list-style:none}
.ds-artifact-card{display:flex;flex-direction:column;min-width:0;overflow:hidden;border:1px solid var(--border);border-radius:var(--radius);background:var(--background)}
.ds-artifact-open{display:flex;flex:1;flex-direction:column;gap:8px;width:100%;min-width:0;padding:16px;border:0;background:transparent;color:var(--foreground);text-align:left}
.ds-artifact-open strong{font-size:14px;font-weight:550;overflow-wrap:anywhere}.ds-artifact-open small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted-foreground);font-size:12px}
.ds-artifact-open:hover{background:var(--muted)}.ds-artifact-open:focus-visible{outline:1px solid var(--foreground);outline-offset:-2px}
.ds-artifact-snippet{display:-webkit-box;overflow:hidden;color:var(--muted-foreground);font-size:13px;line-height:1.55;overflow-wrap:anywhere;white-space:pre-wrap;-webkit-box-orient:vertical;-webkit-line-clamp:6}
.ds-artifact-card footer{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 10px 8px 16px;color:var(--muted-foreground);font-size:11px}.ds-artifact-menu{width:32px;height:32px;border:0;border-radius:var(--radius);background:transparent;color:var(--foreground)}
@media(max-width:900px){.ds-artifact-drop{align-items:stretch;flex-direction:column}}
@media(max-width:767px){.ds-artifact-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ds-artifact-actions button,.ds-artifact-menu{min-height:44px}.ds-artifact-menu{width:44px}}
@media(max-width:480px){.ds-artifact-grid{grid-template-columns:minmax(0,1fr)}}
@media(pointer:coarse){.ds-artifact-actions button,.ds-artifact-menu{min-height:44px}.ds-artifact-menu{width:44px}}

.ds-language-picker{font-family:var(--font-sans)}
.ds-language-trigger{display:inline-flex;align-items:center;gap:8px;min-height:32px;padding:0 10px;border:1px solid transparent;border-radius:var(--radius);background:var(--muted);color:var(--foreground);font:400 12px var(--font-sans)}
.ds-language-trigger:hover{background:color-mix(in oklch,var(--muted) 70%,transparent)}
.ds-language-trigger:focus-visible{outline:2px solid var(--foreground);outline-offset:3px}
.ds-language-popover{width:min(280px,calc(100vw - 24px));max-height:var(--radix-popover-content-available-height);overflow:hidden;padding:0;border-radius:12px;background:var(--popover);color:var(--popover-foreground);box-shadow:0 4px 6px -1px rgb(0 0 0 / .1),0 2px 4px -2px rgb(0 0 0 / .1);outline:1px solid color-mix(in oklch,var(--foreground) 10%,transparent)}
.ds-language-search{display:flex;align-items:center;gap:8px;min-height:48px;padding:0 12px;border-bottom:1px solid var(--border);color:var(--muted-foreground)}
.ds-language-search:focus-within{background:var(--muted)}
.ds-language-search input{min-width:0;flex:1;padding:0;border:0;outline:none;background:transparent;color:var(--foreground);font:400 14px var(--font-sans)}
.ds-language-search input::placeholder{color:var(--muted-foreground)}
.ds-language-options{max-height:min(280px,calc(var(--radix-popover-content-available-height) - 50px));overflow:auto;padding:4px;scrollbar-width:none}
.ds-language-options::-webkit-scrollbar{display:none}
.ds-language-option{display:flex;align-items:center;gap:8px;min-height:36px;padding:8px 10px;border-radius:6px;color:var(--popover-foreground);font-size:14px}
.ds-language-option[aria-selected="true"]{background:var(--muted);color:var(--foreground)}
.ds-language-check{margin-left:auto;opacity:0}
.ds-language-option[data-checked="true"] .ds-language-check{opacity:1}
@media(max-width:767px){.ds-language-option{min-height:44px}}
